add_action( 'woocommerce_after_add_to_cart_button', 'perfectpixel_buy_now_button' );
add_filter( 'woocommerce_add_to_cart_redirect', 'perfectpixel_buy_now_redirect' );

function perfectpixel_buy_now_button() {
	global $product;
	if ( ! $product instanceof WC_Product || ! $product->is_purchasable() || ! $product->is_in_stock() ) {
		return;
	}
	$action = add_query_arg( 'perfectpixel_buy_now', '1', get_permalink( $product->get_id() ) );

	// Simple products send their ID with the clicked button; variable products already have a hidden "add-to-cart" input.
	$name = $product->is_type( 'variable' ) ? '' : sprintf( ' name="add-to-cart" value="%d"', $product->get_id() );

	printf(
		'<button type="submit" class="button alt perfectpixel-buy-now" formaction="%1$s"%2$s>%3$s</button>',
		esc_url( $action ),
		$name, // phpcs:ignore WordPress.Security.EscapeOutput -- Built from an integer.
		esc_html( '{{buy_now_label}}' )
	);
}

function perfectpixel_buy_now_redirect( $url ) {
	if ( ! empty( $_GET['perfectpixel_buy_now'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification
		return wc_get_checkout_url();
	}
	return $url;
}
